def transform(grid):
    if not grid or not grid[0]:
        return grid

    height = len(grid)
    width = len(grid[0])

    from collections import Counter

    # 1. Find separator lines (rows or columns that are monochromatic)
    sep_rows = []
    sep_cols = []

    for r in range(height):
        if len(set(grid[r])) == 1:
            sep_rows.append(r)

    for c in range(width):
        col_vals = [grid[r][c] for r in range(height)]
        if len(set(col_vals)) == 1:
            sep_cols.append(c)

    # 2. Determine separator color (from any identified separator line)
    sep_color = 0
    if sep_rows:
        sep_color = grid[sep_rows[0]][0]
    elif sep_cols:
        sep_color = grid[0][sep_cols[0]]

    # 3. Identify region boundaries
    # Regions lie between separator lines
    # Sort and fill gaps
    sep_rows.sort()
    sep_cols.sort()

    row_ranges = []
    if sep_rows:
        start = 0
        for r in sep_rows:
            if r > start:
                row_ranges.append((start, r - 1))
                start = r + 1
        if start < height:
            row_ranges.append((start, height - 1))
    else:
        row_ranges.append((0, height - 1))

    col_ranges = []
    if sep_cols:
        start = 0
        for c in sep_cols:
            if c > start:
                col_ranges.append((start, c - 1))
                start = c + 1
        if start < width:
            col_ranges.append((start, width - 1))
    else:
        col_ranges.append((0, width - 1))

    # 4. Count 8s in each region and determine background color
    max_8s = 0
    region_count = 0
    bg_color_counts = Counter()

    # Iterate regions to count
