                for c in range(c_start, c_end + 1):
                    val = grid[r][c]
                    if val == 8:
                        c_count += 1
                    elif val != sep_color and val != 8:
                        bg_color_counts[val] += 1
            row_counts.append(c_count)

        # Track max across all regions
        for count in row_counts:
            if count > max_8s:
                max_8s = count

    # Determine background color
    if bg_color_counts:
        bg_color = bg_color_counts.most_common(1)[0][0]
    else:
        bg_color = 0

    # 5. Construct output grid
    # Output dimensions match number of regions
    out_h = len(row_ranges)
    out_w = len(col_ranges)

    # Initialize with background color
    output_grid = [[bg_color for _ in range(out_w)] for _ in range(out_h)]

    # Fill 1s where 8 count matches max (and max > 0 to avoid highlighting empty)
    for r_idx, (r_start, r_end) in enumerate(row_ranges):
        for c_idx, (c_start, c_end) in enumerate(col_ranges):
            # Recalculate count for this specific region to align with output order
