            c_count = 0
            for r in range(r_start, r_end + 1):
                for c in range(c_start, c_end + 1):
                    if grid[r][c] == 8:
                        c_count += 1

            if c_count == max_8s and max_8s > 0:
                output_grid[r_idx][c_idx] = 1

    return output_grid
